@Component("case_-subscriber")
public class Case_Subscriber extends BaseSubscriber {

	public Case_Subscriber() {
	}
	
    public SubscriptionQueryResult<List<Case_>, Case_> case_Subscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllCase_Query(), 
                		ResponseTypes.multipleInstancesOf(Case_.class),
                		ResponseTypes.instanceOf(Case_.class));
    }

    public SubscriptionQueryResult<Case_, Case_> case_Subscribe(@DestinationVariable UUID case_Id) {
        return queryGateway
                .subscriptionQuery(new FindCase_Query(new LoadCase_Filter(case_Id)), 
                		ResponseTypes.instanceOf(Case_.class),
                		ResponseTypes.instanceOf(Case_.class));
    }





}

